package com.toainvocations;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Boss-specific ToA invocations.
 *
 * Widget child indices are derived from the ordinal position in the full invocation list
 * (which includes general invocations before the boss-specific ones), multiplied by 3.
 * The full ordering matches the in-game invocations panel widget children.
 *
 * To verify/update indices: open the invocations panel in-game, check widget 774 child 52,
 * and note that each invocation occupies 3 widget child slots.
 */
@Getter
@RequiredArgsConstructor
public enum ToaInvocation
{
	// Kephri (Path of Scabaras) — full ordinals 20-24
	LIVELY_LARVAE("Lively Larvae", ToaRoom.KEPHRI, 60),
	MORE_OVERLORDS("More Overlords", ToaRoom.KEPHRI, 63),
	BLOWING_MUD("Blowing Mud", ToaRoom.KEPHRI, 66),
	MEDIC("Medic!", ToaRoom.KEPHRI, 69),
	AERIAL_ASSAULT("Aerial Assault", ToaRoom.KEPHRI, 72),

	// Zebak (Path of Crondis) — full ordinals 25-28
	NOT_JUST_A_HEAD("Not Just a Head", ToaRoom.ZEBAK, 75),
	ARTERIAL_SPRAY("Arterial Spray", ToaRoom.ZEBAK, 78),
	BLOOD_THINNERS("Blood Thinners", ToaRoom.ZEBAK, 81),
	UPSET_STOMACH("Upset Stomach", ToaRoom.ZEBAK, 84),

	// Akkha (Path of Het) — full ordinals 29-32
	DOUBLE_TROUBLE("Double Trouble", ToaRoom.AKKHA, 87),
	KEEP_BACK("Keep Back", ToaRoom.AKKHA, 90),
	STAY_VIGILANT("Stay Vigilant", ToaRoom.AKKHA, 93),
	FEELING_SPECIAL("Feeling Special?", ToaRoom.AKKHA, 96),

	// Ba-Ba (Path of Apmeken) — full ordinals 33-37
	MIND_THE_GAP("Mind the Gap!", ToaRoom.BA_BA, 99),
	GOTTA_HAVE_FAITH("Gotta Have Faith", ToaRoom.BA_BA, 102),
	JUNGLE_JAPES("Jungle Japes", ToaRoom.BA_BA, 105),
	SHAKING_THINGS_UP("Shaking Things Up", ToaRoom.BA_BA, 108),
	BOULDERDASH("Boulderdash", ToaRoom.BA_BA, 111),

	// The Wardens — full ordinals 38-43
	ANCIENT_HASTE("Ancient Haste", ToaRoom.WARDENS, 114),
	ACCELERATION("Acceleration", ToaRoom.WARDENS, 117),
	PENETRATION("Penetration", ToaRoom.WARDENS, 120),
	OVERCLOCKED("Overclocked", ToaRoom.WARDENS, 123),
	OVERCLOCKED_2("Overclocked 2", ToaRoom.WARDENS, 126),
	INSANITY("Insanity", ToaRoom.WARDENS, 129);

	private final String displayName;
	private final ToaRoom room;

	/**
	 * Index of this invocation's container widget within the parent widget's children array.
	 * Active state is read from {@code widget.getOnOpListener()[3] == 1}.
	 */
	private final int widgetChildIndex;
}

package com.toainvocations;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("toainvocations")
public interface ToaInvocationsConfig extends Config
{
	enum DisplayMode
	{
		COUNT_ONLY,
		NAMES
	}

	@ConfigItem(
		keyName = "displayMode",
		name = "Display Mode",
		description = "Show only the count of active invocations, or list their names"
	)
	default DisplayMode displayMode()
	{
		return DisplayMode.NAMES;
	}
}

package com.toainvocations;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class ToaInvocationsOverlay extends OverlayPanel
{
	private final ToaInvocationsPlugin plugin;
	private final ToaInvocationsConfig config;

	@Inject
	ToaInvocationsOverlay(ToaInvocationsPlugin plugin, ToaInvocationsConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		ToaRoom room = plugin.getCurrentRoom();
		if (room == null)
		{
			return null;
		}

		List<ToaInvocation> invocations = plugin.getActiveInvocations();
		int count = invocations.size();

		panelComponent.getChildren().clear();

		if (config.displayMode() == ToaInvocationsConfig.DisplayMode.COUNT_ONLY)
		{
			panelComponent.getChildren().add(TitleComponent.builder()
				.text(room.getDisplayName() + " (" + count + ")")
				.build());
		}
		else
		{
			panelComponent.getChildren().add(TitleComponent.builder()
				.text("Invocations (" + count + "):")
				.build());

			for (ToaInvocation inv : invocations)
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left(inv.getDisplayName())
					.build());
			}
		}

		return super.render(graphics);
	}
}

package com.toainvocations;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "ToA Invocations",
	description = "Shows relevant invocations when entering ToA boss rooms",
	tags = {"toa", "tombs", "amascut", "invocations", "raid"}
)
public class ToaInvocationsPlugin extends Plugin
{
	/** Group ID of the ToA invocations/party setup interface. */
	private static final int WIDGET_INVOCATIONS_GROUP = 774;

	/** Child ID of the scrollable invocations list within the group. */
	private static final int WIDGET_INVOCATIONS_CHILD = 52;

	/** Script fired whenever the ToA party/invocations interface is built or a tab is changed. */
	private static final int SCRIPT_TOA_PARTY_BUILD = 6729;

	/** Script fired when toggling between the invocations and reward-panel tabs. */
	private static final int SCRIPT_TOA_PARTY_TOGGLE = 6732;

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ToaInvocationsOverlay overlay;

	/** The boss room the player is currently in, or null if outside a boss room. */
	@Getter
	private ToaRoom currentRoom;

	/**
	 * Active invocations for {@link #currentRoom}.
	 * Empty when not in a boss room or when no invocations have been cached yet.
	 */
	@Getter
	private List<ToaInvocation> activeInvocations = Collections.emptyList();

	/**
	 * All boss-specific invocations that were active the last time the invocations
	 * widget was readable (i.e., when the player had the panel open in the lobby).
	 * Cached across room transitions since invocations are fixed for the raid.
	 */
	private final List<ToaInvocation> cachedActiveInvocations = new ArrayList<>();

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		currentRoom = null;
		activeInvocations = Collections.emptyList();
		cachedActiveInvocations.clear();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			currentRoom = null;
			activeInvocations = Collections.emptyList();
			cachedActiveInvocations.clear();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (client.getLocalPlayer() == null)
		{
			setCurrentRoom(null);
			return;
		}

		LocalPoint lp = client.getLocalPlayer().getLocalLocation();
		if (lp == null)
		{
			setCurrentRoom(null);
			return;
		}

		int regionId = WorldPoint.fromLocalInstance(client, lp).getRegionID();
		setCurrentRoom(ToaRoom.fromRegionId(regionId));
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == WIDGET_INVOCATIONS_GROUP)
		{
			readInvocationsFromWidget();
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		int id = event.getScriptId();
		if (id == SCRIPT_TOA_PARTY_BUILD || id == SCRIPT_TOA_PARTY_TOGGLE)
		{
			readInvocationsFromWidget();
		}
	}

	/**
	 * Reads the currently selected invocations from widget 774 child 52.
	 * This widget is only populated when the ToA invocations panel is open (lobby area).
	 * Results are stored in {@link #cachedActiveInvocations} and used throughout the raid.
	 */
	private void readInvocationsFromWidget()
	{
		Widget parent = client.getWidget(WIDGET_INVOCATIONS_GROUP, WIDGET_INVOCATIONS_CHILD);
		if (parent == null || parent.isHidden() || parent.getChildren() == null)
		{
			return;
		}

		List<ToaInvocation> found = new ArrayList<>();
		for (ToaInvocation invoc : ToaInvocation.values())
		{
			Widget invocWidget = parent.getChild(invoc.getWidgetChildIndex());
			if (invocWidget == null)
			{
				continue;
			}

			Object[] ops = invocWidget.getOnOpListener();
			if (ops == null || ops.length < 4 || !(ops[3] instanceof Integer))
			{
				continue;
			}

			if ((Integer) ops[3] == 1)
			{
				found.add(invoc);
			}
		}

		cachedActiveInvocations.clear();
		cachedActiveInvocations.addAll(found);
		log.debug("Cached {} active boss-specific invocations", cachedActiveInvocations.size());

		// Refresh the displayed invocations for the current room.
		refreshActiveInvocations();
	}

	private void setCurrentRoom(ToaRoom room)
	{
		if (room == currentRoom)
		{
			return;
		}
		currentRoom = room;
		refreshActiveInvocations();
	}

	private void refreshActiveInvocations()
	{
		if (currentRoom == null)
		{
			activeInvocations = Collections.emptyList();
			return;
		}

		List<ToaInvocation> filtered = new ArrayList<>();
		for (ToaInvocation inv : cachedActiveInvocations)
		{
			if (inv.getRoom() == currentRoom)
			{
				filtered.add(inv);
			}
		}
		activeInvocations = filtered;
	}

	@Provides
	ToaInvocationsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ToaInvocationsConfig.class);
	}
}

package com.toainvocations;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum ToaRoom
{
	KEPHRI("Kephri", new int[]{14164}),
	ZEBAK("Zebak", new int[]{15700}),
	AKKHA("Akkha", new int[]{14676}),
	BA_BA("Ba-Ba", new int[]{15188}),
	WARDENS("The Wardens", new int[]{15184, 15696});

	private final String displayName;
	private final int[] regionIds;

	public static ToaRoom fromRegionId(int regionId)
	{
		for (ToaRoom room : values())
		{
			for (int id : room.regionIds)
			{
				if (id == regionId)
				{
					return room;
				}
			}
		}
		return null;
	}
}

